def implants_as_targets(apps, schema_editor):
    """The implants each course asked for become its first target."""
    Course, CourseTarget = apps.get_model("academy", "Course"), apps.get_model("academy", "CourseTarget")
    for course in Course.objects.filter(implants_required__gt=0):
        CourseTarget.objects.get_or_create(course=course, kind="implants",
                                           defaults={"count": course.implants_required})


